from scipy.spatial.transform import Rotation as Rot
import numpy as np, mujoco
class Control:
    def __init__(self,s):
        self.s=s; self.m=s.model; self.d=s.data
        self.ids=np.array([self.m.joint(f'robot0_joint{i}').qposadr[0] for i in range(1,8)])
        self.dofs=np.array([self.m.joint(f'robot0_joint{i}').dofadr[0] for i in range(1,8)])
        self.limits=np.array([self.m.jnt_range[self.m.joint(f'robot0_joint{i}').id] for i in range(1,8)])
        self.site=s.env.robots[0].eef_site_id['right']; self.bottle=self.m.body('obj_0_main').id
        self.kd=mujoco.MjData(self.m); self.a=s.initial_command(); self.Rdown=np.diag([1.,-1.,-1.])
    def pos(self):return self.d.site_xpos[self.site].copy()
    def ori(self):return self.d.site_xmat[self.site].reshape(3,3).copy()
    def obj(self):return self.d.xpos[self.bottle].copy()
    def ik(self,p,R=None,q=None):
        if R is None:R=self.Rdown
        self.kd.qpos[:]=self.d.qpos
        if q is None:q=self.a[:7].copy()
        self.kd.qpos[self.ids]=q
        jp=np.zeros((3,self.m.nv)); jr=jp.copy()
        for i in range(100):
            mujoco.mj_fwdPosition(self.m,self.kd)
            pe=np.array(p)-self.kd.site_xpos[self.site]
            re=Rot.from_matrix(R@self.kd.site_xmat[self.site].reshape(3,3).T).as_rotvec()
            if np.linalg.norm(pe)<0.0002 and np.linalg.norm(re)<0.001:break
            mujoco.mj_jacSite(self.m,self.kd,jp,jr,self.site)
            J=np.vstack([jp[:,self.dofs],jr[:,self.dofs]*.4]); e=np.r_[pe,.4*re]
            dq=J.T@np.linalg.solve(J@J.T+np.eye(6)*.0001,e)
            dq*=min(1,.14/max(np.abs(dq)))
            q=np.clip(q+dq,self.limits[:,0]+.002,self.limits[:,1]-.002)
            self.kd.qpos[self.ids]=q
        return q, np.linalg.norm(pe),np.linalg.norm(re)
    def step(self,a=None):
        if a is not None:self.a=np.array(a).copy()
        self.s.step(self.a)
    def hold(self,n=15,grip=None):
        self.a[8:12]=0
        if grip is not None:self.a[7]=grip
        for _ in range(n):self.step()
    def move(self,p,R=None,n=80,grip=None):
        if R is None:R=self.Rdown
        p0=self.pos(); R0=self.ori(); dr=Rot.from_matrix(R@R0.T).as_rotvec()
        if grip is not None:self.a[7]=grip
        self.a[8:12]=0
        for i in range(1,n+1):
            t=i/n; u=t*t*(3-2*t)
            Ri=Rot.from_rotvec(dr*u).as_matrix()@R0
            q,pe,re=self.ik(p0+(np.array(p)-p0)*u,Ri)
            self.a[:7]=q;self.step()
        self.hold(15)
        print('move',np.round(self.pos(),4),'error',np.linalg.norm(self.pos()-p),'obj',np.round(self.obj(),4),'steps',len(self.s.actions),flush=True)
    def report(self):
        print('eef',self.pos(),'obj',self.obj(),'finger',self.d.qpos[11:13],'check',self.s.check(),flush=True)
